// Purpose: decide whether a candidate generated-documentation tree differs from
// its baseline ONLY by the two differences the maintainer has ruled on, and to
// say precisely which rule each file fell under.
//
// Ruling request RR-2026-09-08-2 registered the two permitted classes:
//
//  1. The contextual JSDoc footer token. Every generated page carries exactly
//     one `Documentation generated by <a …>JSDoc <version></a>` inside its
//     single `<footer>` element. Moving to JSDoc 4.0.5 rewrites that one token.
//  2. Nine anchor corrections across five named pages. JSDoc 4's
//     `templateHelper.js` trims `linkText` and `target`; JSDoc 3 did not, so a
//     source `{@link url |label}` rendered a padded label and an href with a
//     trailing `%20`. The corrections are enumerated below verbatim — old and
//     new anchor HTML plus the exact occurrence count — and NOTHING else is
//     permitted, including a different href, a different label, or a different
//     number of occurrences of a listed anchor.
//
// Everything outside those two classes must match byte for byte: HTML, hrefs,
// labels, file membership, declarations and `types.txt`. There is no global
// whitespace or ordering normalization here, deliberately — the member-ordering
// change is repaired in `Tools/jsdoc/cesium_template/sortDoclets.js`, not
// waived at the comparator.
//
// The classifier that produced RR-2's diagnosis excluded 327 real emitted pages
// because it tested `name.endsWith(".html")` and JSDoc emits fragment-suffixed
// filenames such as `global.html#ANNOTATIONS`. `isHtmlDocumentPath` therefore
// looks at the path portion BEFORE the first literal `#`.

export const FOOTER_TOKEN = Object.freeze({
  baseline: '<a href="https://github.com/jsdoc3/jsdoc">JSDoc 3.6.11</a>',
  candidate: '<a href="https://github.com/jsdoc3/jsdoc">JSDoc 4.0.5</a>',
});

/**
 * The nine permitted anchor corrections, keyed by the documentation-relative
 * file name. `count` is the exact number of occurrences that must change; a
 * tenth occurrence, or a ninth that did not change, is a difference.
 */
export const PERMITTED_ANCHOR_CORRECTIONS = Object.freeze({
  "ArcGisMapServerImageryProvider.html": Object.freeze([
    Object.freeze({
      old: '<a href="https://developers.arcgis.com/documentation/mapping-apis-and-services/security"> ArcGIS Access Token </a>',
      new: '<a href="https://developers.arcgis.com/documentation/mapping-apis-and-services/security">ArcGIS Access Token</a>',
      count: 2,
    }),
  ]),
  "ArcGisMapService.html": Object.freeze([
    Object.freeze({
      old: '<a href="https://developers.arcgis.com/documentation/mapping-apis-and-services/security/%20"> ArcGIS developer guide</a>',
      new: '<a href="https://developers.arcgis.com/documentation/mapping-apis-and-services/security/">ArcGIS developer guide</a>',
      count: 1,
    }),
  ]),
  "Cesium3DTileset.html": Object.freeze([
    Object.freeze({
      old: '<a href="https://github.com/CesiumGS/glTF/tree/draft-splat-spz/extensions/2.0/Khronos/KHR_gaussian_splatting%20"> KHR_gaussian_splatting</a>',
      new: '<a href="https://github.com/CesiumGS/glTF/tree/draft-splat-spz/extensions/2.0/Khronos/KHR_gaussian_splatting">KHR_gaussian_splatting</a>',
      count: 1,
    }),
    Object.freeze({
      old: '<a href="https://github.com/CesiumGS/glTF/tree/draft-splat-spz/extensions/2.0/Khronos/KHR_gaussian_splatting_compression_spz_2%20"> KHR_gaussian_splatting_compression_spz_2</a>',
      new: '<a href="https://github.com/CesiumGS/glTF/tree/draft-splat-spz/extensions/2.0/Khronos/KHR_gaussian_splatting_compression_spz_2">KHR_gaussian_splatting_compression_spz_2</a>',
      count: 1,
    }),
  ]),
  "GaussianSplat3DTileContent.html": Object.freeze([
    Object.freeze({
      old: '<a href="https://github.com/CesiumGS/glTF/tree/draft-splat-spz/extensions/2.0/Khronos/KHR_gaussian_splatting%20"> KHR_gaussian_splatting</a>',
      new: '<a href="https://github.com/CesiumGS/glTF/tree/draft-splat-spz/extensions/2.0/Khronos/KHR_gaussian_splatting">KHR_gaussian_splatting</a>',
      count: 1,
    }),
    Object.freeze({
      old: '<a href="https://github.com/CesiumGS/glTF/tree/draft-splat-spz/extensions/2.0/Khronos/KHR_gaussian_splatting_compression_spz_2%20"> KHR_gaussian_splatting_compression_spz_2</a>',
      new: '<a href="https://github.com/CesiumGS/glTF/tree/draft-splat-spz/extensions/2.0/Khronos/KHR_gaussian_splatting_compression_spz_2">KHR_gaussian_splatting_compression_spz_2</a>',
      count: 1,
    }),
  ]),
  "IntersectionTests.html": Object.freeze([
    Object.freeze({
      old: '<a href="https://cadxfem.org/inf/Fast%20MinimumStorage%20RayTriangle%20Intersection.pdf"> Fast Minimum Storage Ray/Triangle Intersection</a>',
      new: '<a href="https://cadxfem.org/inf/Fast%20MinimumStorage%20RayTriangle%20Intersection.pdf">Fast Minimum Storage Ray/Triangle Intersection</a>',
      count: 2,
    }),
  ]),
});

export const PERMITTED_ANCHOR_OCCURRENCE_TOTAL = Object.values(
  PERMITTED_ANCHOR_CORRECTIONS,
).reduce(
  (total, corrections) =>
    total + corrections.reduce((sum, entry) => sum + entry.count, 0),
  0,
);

/**
 * JSDoc emits pages whose file name carries a literal `#` fragment, e.g.
 * `global.html#ANNOTATIONS`. Classify on the portion before the first `#`.
 */
export function isHtmlDocumentPath(filePath) {
  if (typeof filePath !== "string" || filePath === "") {
    return false;
  }
  const hash = filePath.indexOf("#");
  const withoutFragment = hash === -1 ? filePath : filePath.slice(0, hash);
  return /\.html$/iu.test(withoutFragment);
}

export function documentFileName(filePath) {
  const normalized = String(filePath).replace(/\\/gu, "/");
  const slash = normalized.lastIndexOf("/");
  return slash === -1 ? normalized : normalized.slice(slash + 1);
}

function occurrences(haystack, needle) {
  if (needle === "") {
    return 0;
  }
  let count = 0;
  let index = haystack.indexOf(needle);
  while (index !== -1) {
    count += 1;
    index = haystack.indexOf(needle, index + needle.length);
  }
  return count;
}

const FOOTER_ELEMENT = /<footer>([\s\S]*?)<\/footer>/gu;

/**
 * "Exactly one contextual footer token" — one `<footer>` element, one token in
 * it, and no stray copy of either token anywhere else in the page. An extra
 * token, a missing token, or a token moved out of the footer all fail here.
 */
function footerTokenState(text, token) {
  const total = occurrences(text, token);
  FOOTER_ELEMENT.lastIndex = 0;
  const footers = [...text.matchAll(FOOTER_ELEMENT)];
  const inFooter = footers.reduce(
    (sum, match) => sum + occurrences(match[1], token),
    0,
  );
  return { total, footerCount: footers.length, inFooter };
}

function footerSubstitution(baseline, candidate) {
  const baselineState = footerTokenState(baseline, FOOTER_TOKEN.baseline);
  const candidateState = footerTokenState(candidate, FOOTER_TOKEN.candidate);
  const crossBaseline = occurrences(baseline, FOOTER_TOKEN.candidate);
  const crossCandidate = occurrences(candidate, FOOTER_TOKEN.baseline);

  if (baselineState.total === 0 && candidateState.total === 0) {
    return { applied: false, text: baseline, reason: null };
  }
  if (
    baselineState.total !== 1 ||
    baselineState.inFooter !== 1 ||
    baselineState.footerCount !== 1
  ) {
    return {
      applied: false,
      text: baseline,
      reason: `baseline footer token is not exactly one in one <footer> (total ${baselineState.total}, footers ${baselineState.footerCount}, in-footer ${baselineState.inFooter})`,
    };
  }
  if (
    candidateState.total !== 1 ||
    candidateState.inFooter !== 1 ||
    candidateState.footerCount !== 1
  ) {
    return {
      applied: false,
      text: baseline,
      reason: `candidate footer token is not exactly one in one <footer> (total ${candidateState.total}, footers ${candidateState.footerCount}, in-footer ${candidateState.inFooter})`,
    };
  }
  if (crossBaseline !== 0 || crossCandidate !== 0) {
    return {
      applied: false,
      text: baseline,
      reason: `a footer token appears on the wrong side (candidate token in baseline ${crossBaseline}, baseline token in candidate ${crossCandidate})`,
    };
  }
  return {
    applied: true,
    text: baseline.replace(FOOTER_TOKEN.baseline, FOOTER_TOKEN.candidate),
    reason: null,
  };
}

function applyAnchorCorrections(text, corrections, candidate) {
  const applied = [];
  let working = text;
  for (const correction of corrections) {
    const oldInBaseline = occurrences(working, correction.old);
    const newInCandidate = occurrences(candidate, correction.new);
    const oldInCandidate = occurrences(candidate, correction.old);
    if (oldInBaseline !== correction.count) {
      return {
        ok: false,
        text: working,
        applied,
        reason: `expected ${correction.count} occurrence(s) of the pre-correction anchor in the baseline, found ${oldInBaseline}`,
      };
    }
    if (newInCandidate !== correction.count) {
      return {
        ok: false,
        text: working,
        applied,
        reason: `expected ${correction.count} occurrence(s) of the corrected anchor in the candidate, found ${newInCandidate}`,
      };
    }
    if (oldInCandidate !== 0) {
      return {
        ok: false,
        text: working,
        applied,
        reason: `the pre-correction anchor still appears ${oldInCandidate} time(s) in the candidate`,
      };
    }
    working = working.split(correction.old).join(correction.new);
    applied.push({ anchor: correction.new, count: correction.count });
  }
  return { ok: true, text: working, applied, reason: null };
}

/**
 * Compare one documentation file.
 *
 * @returns {{classification: "raw-equal"|"footer-only"|"anchor-corrected"|"different",
 *            reason: string|null, anchorsApplied: Array<{anchor: string, count: number}>}}
 */
export function compareDocumentationFile({
  path: filePath,
  baseline,
  candidate,
}) {
  if (typeof baseline !== "string" || typeof candidate !== "string") {
    return {
      classification: "different",
      reason: "baseline and candidate must both be strings",
      anchorsApplied: [],
    };
  }
  if (baseline === candidate) {
    return { classification: "raw-equal", reason: null, anchorsApplied: [] };
  }
  if (!isHtmlDocumentPath(filePath)) {
    return {
      classification: "different",
      reason:
        "non-HTML documentation output must match byte for byte; no footer or anchor allowance applies",
      anchorsApplied: [],
    };
  }

  const footer = footerSubstitution(baseline, candidate);
  if (footer.reason !== null) {
    return {
      classification: "different",
      reason: footer.reason,
      anchorsApplied: [],
    };
  }
  if (footer.text === candidate) {
    return { classification: "footer-only", reason: null, anchorsApplied: [] };
  }

  const corrections =
    PERMITTED_ANCHOR_CORRECTIONS[documentFileName(filePath)] ?? [];
  if (corrections.length === 0) {
    return {
      classification: "different",
      reason:
        "content differs after the contextual footer substitution, and this page has no permitted anchor corrections",
      anchorsApplied: [],
    };
  }

  const anchors = applyAnchorCorrections(footer.text, corrections, candidate);
  if (!anchors.ok) {
    return {
      classification: "different",
      reason: anchors.reason,
      anchorsApplied: anchors.applied,
    };
  }
  if (anchors.text !== candidate) {
    return {
      classification: "different",
      reason:
        "content still differs after the contextual footer substitution and every permitted anchor correction",
      anchorsApplied: anchors.applied,
    };
  }
  return {
    classification: "anchor-corrected",
    reason: null,
    anchorsApplied: anchors.applied,
  };
}

/**
 * Compare two whole documentation trees, supplied as `Map<path, string>` (or any
 * iterable of `[path, text]` entries). File membership must match exactly.
 */
export function compareDocumentationTrees({ baseline, candidate }) {
  const baselineFiles = new Map(baseline);
  const candidateFiles = new Map(candidate);
  const missing = [...baselineFiles.keys()]
    .filter((key) => !candidateFiles.has(key))
    .sort();
  const added = [...candidateFiles.keys()]
    .filter((key) => !baselineFiles.has(key))
    .sort();

  const files = [];
  const counts = {
    "raw-equal": 0,
    "footer-only": 0,
    "anchor-corrected": 0,
    different: 0,
  };
  let anchorOccurrences = 0;
  for (const key of [...baselineFiles.keys()].sort()) {
    if (!candidateFiles.has(key)) {
      continue;
    }
    const result = compareDocumentationFile({
      path: key,
      baseline: baselineFiles.get(key),
      candidate: candidateFiles.get(key),
    });
    counts[result.classification] += 1;
    anchorOccurrences += result.anchorsApplied.reduce(
      (sum, entry) => sum + entry.count,
      0,
    );
    files.push({ path: key, ...result });
  }

  const membershipEqual = missing.length === 0 && added.length === 0;
  return {
    status:
      membershipEqual &&
      counts.different === 0 &&
      anchorOccurrences === PERMITTED_ANCHOR_OCCURRENCE_TOTAL
        ? "PASS"
        : "FAIL",
    membership: { equal: membershipEqual, missing, added },
    counts,
    anchorOccurrences,
    expectedAnchorOccurrences: PERMITTED_ANCHOR_OCCURRENCE_TOTAL,
    files,
  };
}
